import os
import shutil
import stat


def encode_component(name, mode=0):
    prefix = ""
    if name.startswith("."):
        prefix += "dot_"
        name = name[1:]
    if mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
        prefix += "executable_"
    if mode & stat.S_IWUSR == 0:
        prefix += "readonly_"
    if mode & stat.S_IRUSR == 0:
        prefix += "private_"
    return prefix + name


def target_to_source(path, dest):
    path = os.path.abspath(os.path.expanduser(path))
    dest = os.path.abspath(os.path.expanduser(dest))
    try:
        rel = os.path.relpath(path, dest)
    except ValueError:
        return None
    if rel == ".." or rel.startswith(".." + os.sep):
        return None
    result = []
    here = dest
    for part in rel.split(os.sep):
        here = os.path.join(here, part)
        try:
            mode = os.lstat(here).st_mode
        except OSError:
            mode = 0
        result.append(encode_component(part, mode))
    return os.path.join(*result) if result else ""


def handle(command, args, source, destination, dry_run=False):
