                    err.append(f"chezmoi: {path}: does not exist")
                    continue
                os.makedirs(os.path.dirname(path), exist_ok=True)
                open(path, "a").close()
            if dry_run:
                out.append(relsource)
                continue
            os.makedirs(os.path.dirname(sourcepath), exist_ok=True)
            if os.path.islink(path):
                if os.path.lexists(sourcepath):
                    os.unlink(sourcepath)
                os.symlink(os.readlink(path), sourcepath)
            elif os.path.isdir(path):
