    try:
        with open(state_path,encoding='utf-8') as f: script_state=json.load(f)
    except (OSError,ValueError): script_state={}
    for name, entry in dump_cmd.entries(source).items():
        if entry.get('type')=='script':
            condition=entry.get('condition','always')
            key=source+'\0'+name
            digest=hashlib.sha256(entry.get('contents','').encode('utf-8')).hexdigest()
            if condition not in ('once','onchange') or script_state.get(key)!=digest:
                result.append((' R',name))
            continue
        path=os.path.join(destination,*name.split('/'))
        if not os.path.lexists(path):
            result.append((' A',name)); continue
        if entry.get('type')=='symlink':
            if not os.path.islink(path) or os.readlink(path)!=entry.get('linkname',''):
                result.append((' M',name))
            continue
        if entry.get('type')=='dir':
            if not os.path.isdir(path) or os.path.islink(path):
                result.append((' M',name))
            elif stat.S_IMODE(os.stat(path).st_mode)!=entry.get('perm',0o755):
                result.append((' M',name))
            continue
        try:
            if os.path.islink(path) or not os.path.isfile(path):
                result.append((' M',name)); continue
            with open(path,'rb') as f: contents=f.read()
            if contents != entry.get('contents','').encode('utf-8') or stat.S_IMODE(os.stat(path).st_mode)!=entry.get('perm',0o644):
                result.append((' M',name))
        except (OSError,UnicodeError):
            result.append((' M',name))
    result.sort(key=lambda item: (dump_cmd.SCRIPT_PHASES.get(item[1], 2), item[1]))
    return result


def handle(command, source, destination, args=()):
