def _ignore_match(path, pattern):
    """Match a source-root-relative glob without letting '*' cross '/' ."""
    path=path.strip('/').split('/') if path.strip('/') else []
    pattern=pattern.strip('/').split('/') if pattern.strip('/') else []
    def match(i,j):
        if j==len(pattern): return i==len(path)
        if pattern[j]=='**':
            return match(i,j+1) or (i<len(path) and match(i+1,j))
        return i<len(path) and fnmatch.fnmatchcase(path[i],pattern[j]) and match(i+1,j+1)
    return match(0,0)

